/* @lc app=leetcode id=1932 lang=kotlin */

class Solution { fun canMerge(trees: List<TreeNode>): TreeNode? = HashMap<Int, TreeNode>().apply { trees.forEach { put(it.`val`, it) } }.let { map -> trees.flatMap { listOfNotNull(it.left?.`val`, it.right?.`val`) }.toSet().let { leaves -> trees.firstOrNull { !leaves.contains(it.`val`) }?.let { root -> map.remove(root.`val`).let { object { fun dfs(node: TreeNode?, min: Long, max: Long): Boolean = if (node == null) true else if (node.`val` <= min || node.`val` >= max) false else node.left?.`val`?.let { map.remove(it) }?.let { node.left = it }.run { node.right?.`val`?.let { map.remove(it) }?.let { node.right = it } }.run { dfs(node.left, min, node.`val`.toLong()) && dfs(node.right, node.`val`.toLong(), max) } }.dfs(root, Long.MIN_VALUE, Long.MAX_VALUE) && map.isEmpty() }.let { if (it) root else null } } } } }